import{_ as n,a0 as o,w as p,s as d,ao as r,I as l,x as i,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"如何在 Linux 上锁定虚拟控制台会话 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上锁定虚拟控制台会话 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上锁定虚拟控制台会话 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上锁定虚拟控制台会话 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20181012 How To Lock Virtual Console Sessions On Linux","title":"如何在 Linux 上锁定虚拟控制台会话","tag":"201810","desc":""},"relativePath":"201810/20181012 How To Lock Virtual Console Sessions On Linux.md","filePath":"[post].md"}'),h={name:"201810/20181012 How To Lock Virtual Console Sessions On Linux.md"};function c(k,s,g,u,b,f){const e=o("Link");return p(),d("div",null,[s[15]||(s[15]=r(`<h1 id="如何在-linux-上锁定虚拟控制台会话" tabindex="-1">如何在 Linux 上锁定虚拟控制台会话 <a class="header-anchor" href="#如何在-linux-上锁定虚拟控制台会话" aria-label="Permalink to “如何在 Linux 上锁定虚拟控制台会话”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/vlock-720x340.png" alt=""></p><p>当你在共享的系统上工作时，你可能不希望其他用户偷窥你的控制台中看你在做什么。如果是这样，我知道有个简单的技巧来锁定自己的会话，同时仍然允许其他用户在其他虚拟控制台上使用该系统。要感谢 <strong>Vlock</strong>（<strong>V</strong>irtual Console <strong>lock</strong>），这是一个命令行程序，用于锁定 Linux 控制台上的一个或多个会话。如有必要，你可以锁定整个控制台并完全禁用虚拟控制台切换功能。Vlock 对于有多个用户访问控制台的共享 Linux 系统特别有用。</p><h3 id="安装-vlock" tabindex="-1">安装 Vlock <a class="header-anchor" href="#安装-vlock" aria-label="Permalink to “安装 Vlock”">​</a></h3><p>在基于 Arch 的系统上，Vlock 软件包被替换为默认预安装的 <strong>kpd</strong> 包，因此你无需为安装烦恼。</p><p>在 Debian、Ubuntu、Linux Mint 上，运行以下命令来安装 Vlock：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install vlock</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install vlock</span></span></code></pre></div><p>在 RHEL、CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install vlock</span></span></code></pre></div><h3 id="在-linux-上锁定虚拟控制台会话" tabindex="-1">在 Linux 上锁定虚拟控制台会话 <a class="header-anchor" href="#在-linux-上锁定虚拟控制台会话" aria-label="Permalink to “在 Linux 上锁定虚拟控制台会话”">​</a></h3><p>Vlock 的一般语法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vlock [ -acnshv ] [ -t &lt;timeout&gt; ] [ plugins... ]</span></span></code></pre></div><p>这里：</p><ul><li><code>a</code> —— 锁定所有虚拟控制台会话，</li><li><code>c</code> —— 锁定当前虚拟控制台会话，</li><li><code>n</code> —— 在锁定所有会话之前切换到新的空控制台，</li><li><code>s</code> —— 禁用 SysRq 键机制，</li><li><code>t</code> —— 指定屏保插件的超时时间，</li><li><code>h</code> —— 显示帮助，</li><li><code>v</code> —— 显示版本。</li></ul><p>让我举几个例子。</p><h4 id="_1、-锁定当前控制台会话" tabindex="-1">1、 锁定当前控制台会话 <a class="header-anchor" href="#_1、-锁定当前控制台会话" aria-label="Permalink to “1、 锁定当前控制台会话”">​</a></h4><p>在没有任何参数的情况下运行 Vlock 时，它默认锁定当前控制台会话 （TYY）。要解锁会话，你需要输入当前用户的密码或 root 密码。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vlock</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/vlock-1-1.gif" alt=""></p><p>你还可以使用 <code>-c</code> 标志来锁定当前的控制台会话。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vlock -c</span></span></code></pre></div><p>请注意，此命令仅锁定当前控制台。你可以按 <code>ALT+F2</code> 切换到其他控制台。有关在 TTY 之间切换的更多详细信息，请参阅以下指南。</p><p>此外，如果系统有多个用户，则其他用户仍可以访问其各自的 TTY。</p><h4 id="_2、-锁定所有控制台会话" tabindex="-1">2、 锁定所有控制台会话 <a class="header-anchor" href="#_2、-锁定所有控制台会话" aria-label="Permalink to “2、 锁定所有控制台会话”">​</a></h4><p>要同时锁定所有 TTY 并禁用虚拟控制台切换功能，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vlock -a</span></span></code></pre></div><p>同样，要解锁控制台会话，只需按下回车键并输入当前用户的密码或 root 用户密码。</p><p>请记住，<strong>root 用户可以随时解锁任何 vlock 会话</strong>，除非在编译时禁用。</p><h4 id="_3、-在锁定所有控制台之前切换到新的虚拟控制台" tabindex="-1">3、 在锁定所有控制台之前切换到新的虚拟控制台 <a class="header-anchor" href="#_3、-在锁定所有控制台之前切换到新的虚拟控制台" aria-label="Permalink to “3、 在锁定所有控制台之前切换到新的虚拟控制台”">​</a></h4><p>在锁定所有控制台之前，还可以使 Vlock 从 X 会话切换到新的空虚拟控制台。为此，请使用 <code>-n</code> 标志。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vlock -n</span></span></code></pre></div><h4 id="_4、-禁用-sysrq-机制" tabindex="-1">4、 禁用 SysRq 机制 <a class="header-anchor" href="#_4、-禁用-sysrq-机制" aria-label="Permalink to “4、 禁用 SysRq 机制”">​</a></h4><p>你也许知道，魔术 SysRq 键机制允许用户在系统死机时执行某些操作。因此，用户可以使用 SysRq 解锁控制台。为了防止这种情况，请传递 <code>-s</code> 选项以禁用 SysRq 机制。请记住，这个选项只适用于有 <code>-a</code> 选项的时候。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vlock -sa</span></span></code></pre></div><p>有关更多选项及其用法，请参阅帮助或手册页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vlock -h</span></span>
<span class="line"><span>$ man vlock</span></span></code></pre></div><p>Vlock 可防止未经授权的用户获得控制台访问权限。如果你在为 Linux 寻找一个简单的控制台锁定机制，那么 Vlock 值得一试！</p><p>就是这些了。希望这篇文章有用。还有更多好东西。敬请关注！</p><p>干杯!</p><hr>`,42)),l("p",null,[s[1]||(s[1]=i("via: ",-1)),a(e,{href:"https://www.ostechnix.com/how-to-lock-virtual-console-sessions-on-linux/"},{default:t(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/how-to-lock-virtual-console-sessions-on-linux/",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=i("作者：",-1)),a(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[7]||(s[7]=i(" 选题：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 译者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[i("Linux中国",-1)])]),_:1}),s[14]||(s[14]=i(" 荣誉推出",-1))])])}const C=n(h,[["render",c]]);export{v as __pageData,C as default};
